(window.GO_WEB=window.GO_WEB||{})["pl"]={"felles":{"_sprak":"Język","nav_browse":"Zobacz konkursy","nav_submit":"Zgłoś konkurs","nav_privacy":"Prywatność","hjem":"Strona główna"},"index":{"_title":"GiveOwl – Konkursy z nagrodami w jednym miejscu","_desc":"GiveOwl zbiera konkursy, loterie i giveawaye, w których możesz wziąć udział, a w sezonie także kalendarze adwentowe online. Za darmo, bez konta, a zgłaszasz się zawsze u organizatora.","h1":"Znajdź darmowe konkursy i <em>kalendarze adwentowe</em> online","lead":"Za darmo i bez konta. Zawsze bierzesz udział u organizatora.","cta":"Zobacz konkursy","snart":"Wkrótce w","senere":"Później w","h2_hva":"Co robi GiveOwl","under_hva":"Jedna uporządkowana lista zamiast stu kart w przeglądarce.","k1_t":"Dopasowane do Twojego kraju","k1":"GiveOwl wybiera kraj na podstawie urządzenia: USA, Wielka Brytania, Kanada, kraje nordyckie i wkrótce kolejne. Możesz go zmienić w każdej chwili.","k2_t":"Bez zakupu","k2":"Filtr jest domyślnie włączony, więc widzisz tylko darmowe konkursy. Termin, nagroda i sposób udziału na pierwszy rzut oka.","k3_t":"Kalendarze adwentowe w sezonie","k3":"W listopadzie i grudniu kalendarze adwentowe online mają własną kartę z dzisiejszymi okienkami Twoich ulubionych.","trygg_t":"My tylko podajemy link. Zgłaszasz się u organizatora.","trygg":"GiveOwl nigdy nie zbiera Twoich zgłoszeń, nie wymaga konta i nic nie kosztuje. Przed udziałem zawsze przeczytaj oficjalny regulamin na stronie organizatora.","h2_arr":"Organizujesz konkurs?","under_arr":"Daj nam znać. Wpis jest bezpłatny.","cta_arr":"Zgłoś konkurs","fot":"GiveOwl nie jest powiązany z wymienionymi organizatorami. © 2026 HENDT AS, Norwegia.","fot_aff":"Pozycje oznaczone jako „Reklama” lub „Sponsorowane” to płatne miejsca lub linki afiliacyjne. Jeśli przez nie weźmiesz udział lub coś kupisz, możemy otrzymać prowizję bez dodatkowych kosztów dla Ciebie. Nigdy nie decyduje to o tym, które konkursy umieszczamy. <a href=\"/privacy/#ads\">Więcej</a>"},"submit":{"_title":"Zgłoś konkurs – GiveOwl","h1":"Zgłoś konkurs","lead":"Organizujesz konkurs, loterię lub kalendarz adwentowy online? Daj nam znać. Wpis jest bezpłatny, a każde zgłoszenie sprawdzamy przed publikacją.","f_arr":"Organizator / marka *","f_tittel":"Nazwa konkursu *","f_premie":"Nagroda/nagrody *","p_premie":"np. karta podarunkowa 500 zł, 3 zwycięzców","f_type":"Rodzaj","o_konk":"Konkurs / loteria / giveaway","o_jul":"Kalendarz adwentowy online","f_land":"Dla mieszkańców kraju *","o_int":"Cały świat","f_start":"Data rozpoczęcia","f_slutt":"Data zakończenia / termin *","f_url":"Link do konkursu lub regulaminu (Twoja strona) *","f_delta":"Jak wziąć udział","p_delta":"np. Wypełnij formularz raz dziennie. Osoby pełnoletnie.","f_kjop":"Bez zakupu (jest darmowy sposób udziału)","f_epost":"Twój e-mail (żebyśmy mogli odpowiedzieć) *","f_ok":"Jestem organizatorem lub mam zgodę na zgłoszenie, a dane są prawidłowe.","send":"Wyślij e-mailem","kopier":"Kopiuj dane","ft_t":"Wyróżnij swój konkurs","ft_lead":"Chcesz więcej uczestników? Pozycje sponsorowane pojawiają się blisko początku listy (maksymalnie dwie naraz) i zawsze są wyraźnie oznaczone jako „Sponsorowane”. Zwykłe wpisy pozostają bezpłatne.","ft_1":"Miejsce blisko początku listy w wybranych krajach","ft_2":"Wyraźne oznaczenie „Sponsorowane”, zgodnie z przepisami o reklamie","ft_3":"Te same zasady jakości co dla każdego wpisu: prawdziwy organizator, oficjalny regulamin, żadnych ukrytych opłat","ft_pris_t":"Cena:","ft_pris":"cena startowa od 25 EUR / 29 USD / 290 NOK za tydzień. Zwykłe wpisy pozostają bezpłatne.","ft_se":"Zobacz ceny i sposób rezerwacji","ft_cta":"Napisz na info@hendtas.com","merk":"Ta strona niczego nie zapisuje. „Wyślij e-mailem” otwiera Twój program pocztowy z wypełnionymi danymi. Zobacz naszą <a href=\"/privacy/\">politykę prywatności</a>.","mangler":"Wypełnij wymagane pola (*).","kopiert":"Skopiowano. Wklej to do e-maila na adres ","aapner":"Otwieranie programu pocztowego…"},"privacy":{"_title":"GiveOwl – Polityka prywatności","_html":"<div class=\"card binding\"><b>To tłumaczenie służy wyłącznie Twojej wygodzie. Wiążąca jest tylko wersja angielska; w razie rozbieżności obowiązuje tekst angielski.</b> <a href=\"#en\">English</a></div>\n<h1>Polityka prywatności GiveOwl</h1>\n<p class=\"meta\">Ostatnia aktualizacja: 17 października 2026 · Dotyczy aplikacji GiveOwl na Androida i iPhone’a (<code>com.hendtas.giveowl</code>) oraz strony giveowl.com</p>\n<div class=\"card\"><b>W skrócie:</b> GiveOwl to katalog konkursów, loterii, giveawayów i kalendarzy adwentowych online. Nie ma kont użytkowników, banerów reklamowych, zakupów ani analityki odwiedzin. Strona zlicza tylko anonimowo kliknięcia w linki do sklepów. Strona zawiera oznaczone linki afiliacyjne (zob. punkt 5a). Ulubione i ustawienia są zapisywane tylko na Twoim urządzeniu. Gdy bierzesz udział w konkursie, robisz to na stronie organizatora. To, co tam podasz, trafia do organizatora, nie do nas. Nie sprzedajemy ani nie udostępniamy danych osobowych.</div>\n<h2>1. Kto jest administratorem?</h2>\n<p>Administratorem jest HENDT AS, Norwegia. E-mail: <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a>.</p>\n<h2>2. Co jest zapisywane na Twoim urządzeniu</h2>\n<p>Poniższe dane są zapisywane lokalnie w aplikacji (lub w przeglądarce na giveowl.com). Nie mamy do nich dostępu i nie są do nas wysyłane:</p>\n<ul><li>które konkursy i kalendarze oznaczyłeś jako ulubione;</li><li>w których konkursach oznaczyłeś udział („Moje zgłoszenia” i „Dziś”) i w jakie dni – na potrzeby serii i siatki kalendarza adwentowego;</li><li>Twoje ustawienia: język, kraj, filtry i sortowanie (np. „Bez zakupu”) oraz ustawienia przypomnień;</li><li>kopia ostatnio pobranej listy, aby aplikacja działała offline.</li></ul>\n<p>Język i kraj są wybierane na podstawie ustawień urządzenia przy pierwszym uruchomieniu GiveOwl. Dzieje się to na urządzeniu; nie używamy Twojej lokalizacji. Jeśli masz włączoną automatyczną kopię zapasową Androida, może ona obejmować dane aplikacji w kopii na Twoim koncie Google. Wszystkie dane możesz usunąć, odinstalowując aplikację, używając opcji „Wyczyść pamięć” w ustawieniach Androida lub czyszcząc dane witryny w przeglądarce. Na iPhonie dane aplikacji mogą trafić do kopii zapasowej iCloud lub urządzenia, jeśli ją włączyłeś. Wszystkie dane usuniesz, usuwając aplikację.</p>\n<p>GiveOwl nie ma logowania, reklam, zakupów w aplikacji, analityki, śledzących plików cookie ani raportowania awarii. Aplikacja nie prosi o dostęp do lokalizacji, kontaktów, aparatu, mikrofonu ani plików.</p>\n<h3>Przypomnienia</h3>\n<p>Jeśli włączysz przypomnienia, aplikacja poprosi Androida o zgodę na wyświetlanie powiadomień. Przypomnienia (np. dzień przed końcem ulubionego konkursu) są planowane lokalnie na urządzeniu przez Androida. Żadne dane przypomnień nie są wysyłane do nas ani do usług push, a przypomnienia możesz w każdej chwili wyłączyć w aplikacji lub w ustawieniach Androida. Na iPhonie aplikacja w ten sam sposób prosi iOS o zgodę, a przypomnienia są planowane lokalnie przez iOS. Możesz je wyłączyć w aplikacji lub w Ustawieniach iOS.</p>\n<h3>Udostępnianie</h3>\n<p>Gdy stukniesz „Udostępnij”, otworzy się menu udostępniania Androida z linkiem do wpisu na giveowl.com. To Ty wybierasz aplikację, a obowiązuje jej polityka prywatności. Nic nie jest wysyłane do nas. Na iPhonie w ten sam sposób otwiera się menu udostępniania iOS.</p>\n<h3>Ocena aplikacji</h3>\n<p>Gdy przez jakiś czas korzystasz z aplikacji na Androida, może ona poprosić Google Play o wyświetlenie okna oceny Google (nie częściej niż raz na 90 dni). Jeśli wystawisz ocenę lub opinię, trafia ona do Google Play i jest przetwarzana zgodnie z warunkami i polityką prywatności Google, tak jak opinia napisana w Sklepie Play. GiveOwl nie otrzymuje z tego okna żadnych informacji, nawet tego, czy wystawiłeś ocenę. Na iPhonie aplikacja może poprosić iOS o wyświetlenie okna oceny Apple (Apple pokazuje je najwyżej trzy razy w roku). Ocena trafia do Apple i jest przetwarzana zgodnie z warunkami Apple; GiveOwl nic nie otrzymuje.</p>\n<h2>3. Aktualizacja listy</h2>\n<p>Aby pokazywać nowe konkursy, aplikacja pobiera zaktualizowaną listę z <code>https://giveowl.com/data.json</code>. Żądanie nie zawiera informacji o Tobie, ale jak przy każdym żądaniu w sieci serwer widzi Twój adres IP i informacje techniczne, np. typ urządzenia lub przeglądarki. Usługa hostująca stronę i listę, GitHub Pages (GitHub, Inc.), może przechowywać takie dane w krótkotrwałych logach technicznych zgodnie z własnymi zasadami. Nie używamy tych danych do identyfikowania Cię.</p>\n<p>Jeśli włączysz w aplikacji na Androida powiadomienia o „Nowych pozycjach”, Android pobiera tę samą listę w tle mniej więcej dwa razy na dobę, tylko gdy masz połączenie z internetem. Aplikacja porównuje ją na urządzeniu z pozycjami, które już widziałeś, i pokazuje jedno powiadomienie, jeśli pojawiło się coś nowego. Lista widzianych pozycji zostaje na urządzeniu, a zapytanie jest takie samo jak powyżej: nie zawiera żadnych informacji o Tobie. Możesz to wyłączyć w każdej chwili w ustawieniach aplikacji. Na iPhonie to iOS decyduje, kiedy następuje pobieranie w tle (Odświeżanie w tle). Jeśli giveowl.com jest niedostępne, aplikacja pobiera ten sam publiczny plik z GitHuba (raw.githubusercontent.com); to żądanie również nie zawiera informacji o Tobie.</p>\n<h2>4. Zgłaszanie konkursu</h2>\n<p>Strona „Zgłoś konkurs” na giveowl.com niczego nie zapisuje. Przygotowuje wiadomość w Twoim programie pocztowym. Jeśli ją wyślesz, otrzymamy wpisane dane i Twój adres e-mail i użyjemy ich wyłącznie do sprawdzenia wpisu i odpowiedzi. Usuwamy wiadomość, gdy przestaje być potrzebna, zwykle w ciągu 12 miesięcy.</p>\n<h2>5. Linki do organizatorów</h2>\n<p>GiveOwl tylko podaje linki. Gdy stukniesz „Weź udział u organizatora”, strona organizatora otworzy się w przeglądarce i obowiązują jej oficjalny regulamin oraz polityka prywatności. Nie odpowiadamy za konkursy, nagrody ani za to, jak organizatorzy przetwarzają Twoje dane. Płatne pozycje są oznaczone jako „Sponsorowane”, a linki afiliacyjne jako „Reklama” (zob. punkt 5a).</p>\n<h2 id=\"tr-ads\">5a. Pozycje sponsorowane, linki afiliacyjne i reklamy</h2>\n<p>GiveOwl może pokazywać pozycje sponsorowane (oznaczone jako „Sponsorowane”) i linki afiliacyjne (oznaczone jako „Reklama”). Przy linku afiliacyjnym organizator lub sieć afiliacyjna może zapłacić nam prowizję, jeśli po kliknięciu weźmiesz udział lub coś kupisz. Nie kosztuje Cię to nic więcej. Płatności nigdy nie decydują o tym, które konkursy umieszczamy ani jak je opisujemy, a umieszczamy tylko konkursy spełniające nasze zasady jakości.</p>\n<p>Gdy otworzysz taki link, otworzy się on w przeglądarce, a sieć afiliacyjna lub organizator mogą używać na swojej stronie plików cookie lub podobnych technologii, aby zarejestrować, że przyszedłeś z GiveOwl. Dzieje się to na podstawie ich polityki prywatności, nie w aplikacji GiveOwl. Sama aplikacja Cię nie śledzi.</p>\n<p>GiveOwl nie wyświetla obecnie reklam w aplikacji. Jeśli w przyszłości dodamy reklamy, najpierw zaktualizujemy tę politykę i informacje o bezpieczeństwie danych aplikacji.</p>\n<h2>6. Dzieci</h2>\n<p>GiveOwl jest przeznaczony dla dorosłych w wieku 18+, ponieważ większość konkursów przyjmuje zgodnie z regulaminem tylko uczestników pełnoletnich (niektóre 21+). GiveOwl nie jest skierowany do dzieci. Nie zbieramy świadomie danych osobowych dzieci, a aplikacja nie zbiera danych osobowych od nikogo.</p>\n<h2>7. Twoje prawa</h2>\n<p>W zależności od miejsca zamieszkania (np. na podstawie RODO w EOG i Wielkiej Brytanii lub stanowych przepisów USA, takich jak CCPA/CPRA) możesz mieć prawo dostępu do danych, ich sprostowania, usunięcia lub ograniczenia przetwarzania, do przenoszenia danych, do sprzeciwu oraz do rezygnacji ze sprzedaży lub udostępniania danych osobowych. Nie sprzedajemy ani nie udostępniamy danych osobowych i nie mamy kont użytkowników, więc zazwyczaj nie możemy powiązać żadnych danych z Tobą. Napisz do nas na <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a>, a pomożemy. Nie będziesz dyskryminowany za korzystanie ze swoich praw. W EOG możesz też złożyć skargę do norweskiego organu ochrony danych (Datatilsynet, <a href=\"https://www.datatilsynet.no/en/\">datatilsynet.no</a>) lub do lokalnego organu (w Polsce: Prezes UODO).</p>\n<h2>8. Zmiany</h2>\n<p>Aktualizujemy tę politykę, gdy GiveOwl się zmienia, np. po dodaniu funkcji lub dostawców usług. Data u góry wskazuje aktualną wersję.</p>\n<h2>9. Kontakt</h2>\n<p>HENDT AS · Norwegia · <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a></p>\n"},"seo":{"g_h1":"Konkursy z nagrodami: {land}","g_title":"Konkursy z nagrodami – {land} ({m}) – GiveOwl","g_desc":"{n} trwających konkursów dla mieszkańców kraju {land}, sprawdzone {d}. Termin, nagroda i sposób udziału u organizatora.","g_desc_int":"{n} trwających konkursów dla mieszkańców kraju {land}, w tym {w} ogólnoświatowych, sprawdzone {d}. Termin, nagroda i sposób udziału.","a_h1":"Kalendarze adwentowe online {y}: {land}","a_title":"Kalendarze adwentowe online {y} – {land} – GiveOwl","a_desc":"Kalendarze adwentowe online {y} ({land}): {n} pozycji, daty, nagrody i jak wziąć udział.","a_all_h1":"Kalendarze adwentowe online {y}","a_all_desc":"Kalendarze adwentowe online {y} z różnych krajów, z nagrodami i sposobem udziału u organizatora.","intro":"Każdy konkurs prowadzi do oficjalnego regulaminu organizatora. GiveOwl nigdy nie zbiera Twoich zgłoszeń.","open":"Trwa","ended":"Zakończony","coming":"Wkrótce","deadline":"Termin","prize":"Nagroda","how":"Jak wziąć udział","enter":"Weź udział u organizatora","app":"Przypomnienia i dzienna lista w aplikacji GiveOwl: dostępna w Google Play.","browse":"Otwórz pełną listę z filtrami","other":"Inne kraje","ended_note":"Ten konkurs się zakończył. Zobacz trwające konkursy: {land}.","nopurchase":"Bez zakupu","purchase":"Wymaga zakupu","updated":"Zaktualizowano {d}","worldwide":"Cały świat","rules":"Oficjalny regulamin","org_lang":"Nagroda i zasady są podane w języku organizatora.","bycountry":"Przeglądaj według kraju","expected":"Oczekiwany – jeszcze niepotwierdzony na 2026","f_end_h1":"Konkursy, które wkrótce się kończą: {land}","f_end_desc":"{n} konkursów ({land}) kończących się w ciągu 7 dni. Sprawdzono {d}.","f_new_h1":"Nowe konkursy w tym tygodniu: {land}","f_new_desc":"{n} konkursów ({land}) dodanych w ostatnich 7 dniach.","f_daily_h1":"Konkursy z codziennym udziałem: {land}","f_daily_desc":"{n} konkursów ({land}), w których można brać udział codziennie.","f_lists":"Więcej list","f_rss":"Kanał RSS"}};
